const {F,T,X,S,G,D}=require('../author.cjs');
const grid=(a,b,n,f)=>Array.from({length:n+1},(_,i)=>{const x=a+(b-a)*i/n;return[x,f(x)];});
const chart=(id,title,caption,reading,x,y,xLabel,yLabel,series)=>G({id,title,caption,reading,plot:{x,y,xLabel,yLabel,series}});
const value=(x,lambda)=>x>=0?Math.sqrt(x):-lambda*Math.sqrt(-x);
const saving=(n,delay=0)=>{let w=0;for(let t=1;t<=n;t++)w=w*1.06+(t>delay?1000:0);return w;};
const feedback=n=>{let prev=100,current=108;if(n===0)return prev;if(n===1)return current;for(let t=2;t<=n;t++){const next=current+.4*(120-current)+.6*(current-prev);prev=current;current=next;}return current;};
module.exports={id:'behavioral',intro:[
 'Verhaltensfehler sind systematische Tendenzen beim Wahrnehmen, Verarbeiten oder Bewerten von Entscheidungen. Das Ziel ist nicht, jede schlechte Rendite nachträglich mit einem psychologischen Etikett zu erklären. Man untersucht den damaligen Entscheidungsweg, seine Informationen und die tatsächlichen wirtschaftlichen Alternativen.',
 'CFA Level I 2027: The Behavioral Biases of Individuals, drei Lernziele. Die Einheit vergleicht kognitive und emotionale Verzerrungen, erläutert die einzelnen Mechanismen und verbindet sie vorsichtig mit möglichen Markteigenschaften. Die Einteilung folgt der ergänzenden öffentlichen CFA-Konzeptübersicht. In der Wirklichkeit können mehrere Mechanismen zusammenwirken.',
 'Alle Personen, Zahlen und Kurvenmodelle sind eigene Beispiele. Psychologische Wertfunktionen sind ausdrücklich illustrative Annahmen, keine Schätzung einer bestimmten Person. Verteilungsrechnungen setzen ihre Wahrscheinlichkeiten voraus. Marktanomalien und historische Beobachtungen sind keine sichere Anleitung zu einer nach Kosten profitablen Handelsstrategie.'
],sections:[
 S('orientation','Die Entscheidung beurteilen, bevor man das Ergebnis kennt','a',[
  'Eine ex ante nachvollziehbare Entscheidung kann einen Verlust erzeugen; ein fehlerhafter Prozess kann zufällig gewinnen. Deshalb werden Informationen, Alternativen, Annahmen und damalige Begründungen dokumentiert. Erst danach lässt sich prüfen, ob ein wiederkehrender Fehler vorlag.',
  X('Ein Gewinn ist kein Beweis für gute Analyse','Zwei Analysten kaufen dieselbe Aktie. A prüft Cashflows, Risiken und Gegenargumente; B kauft allein, weil ein kürzlich erfolgreicher Bekannter sie erwähnt. Die Aktie steigt.',[
   'Der gemeinsame Gewinn zeigt zunächst den beobachteten Preisverlauf. Er macht die Begründungen nicht gleichwertig und belegt bei B keine kausale Prognosefähigkeit.',
   'Umgekehrt würde ein Rückgang nicht automatisch jeden Schritt von A widerlegen. Neue Daten und falsche Annahmen werden konkret untersucht; das Ergebnis ersetzt keine Prozessprüfung.'
  ],'Eine Fehlerdiagnose braucht den Entscheidungsmechanismus und nicht nur einen nachträglichen Gewinn oder Verlust.')
 ]),
 S('categories','Kognitive Fehler und emotionale Verzerrungen','a',[
  T(['Gruppe','Typischer Mechanismus','Eigener Fall','Mögliche Antwort'],[['Kognitiv: Festhalten an Überzeugungen','Neue Information unzureichend oder einseitig einordnen','Eine These bleibt trotz ausdrücklich relevanter Gegenbelege unverändert','Gegenhypothesen, Daten und Aktualisierungsregeln prüfen'],['Kognitiv: Informationsverarbeitung','Wahrscheinlichkeiten, Bezugsgrößen oder Darstellungen fehlerhaft nutzen','Trefferquote eines Signals mit der Wahrscheinlichkeit der Hypothese nach dem Signal verwechseln','Häufigkeitstabelle und gemeinsame Bezugsbasis verwenden'],['Emotional','Impulse oder Gefühle prägen die Bewertung','Aus Furcht vor späterem Bedauern eine ungeeignete Konzentration unverändert lassen','Gefühl anerkennen und Folgen mit tragfähigen Regeln begrenzen']],'Die Gruppierung benennt den dominierenden Mechanismus. Sie ist keine Behauptung, dass Denken und Gefühle vollständig getrennt funktionieren.'),
  'Kognitive Fehler lassen sich häufig eher durch bessere Information, Rechnung oder Entscheidungsstruktur vermindern. Emotionale Reaktionen können hartnäckiger sein; eine sinnvolle Anpassung kann nötig sein. Häufiger bedeutet nicht immer: Auch ein Rechenfehler kann trotz Aufklärung bestehen bleiben und auch eine emotionale Reaktion kann sich verändern.'
 ]),
 S('diagnosis','Eine Präferenz ist nicht automatisch ein Bias','a',[
  'Ein Anleger darf geringe Risiken bevorzugen oder bestimmte Anlagen aus Werten ausschließen. Das ist nicht schon ein Denkfehler. Ebenso können Steuern, Transaktionskosten, fehlende Liquidität und Informationskosten erklären, warum eine bestehende Position nicht sofort verändert wird.',
  'Ein Biasverdacht wird stärker, wenn bei unveränderter wirtschaftlicher Situation allein eine irrelevante Darstellung, ein früherer Kaufpreis oder ein Eigentumsetikett die Entscheidung verändert. Vor der Einordnung wird deshalb geprüft, ob sich tatsächlich nur dieser irrelevante Faktor geändert hat.',
  D('Keine Ferndiagnose aus einem einzelnen Trade',['Eine einzelne geerbte Aktie zu behalten beweist keinen Endowment Bias. Es könnten steuerliche Folgen, eine Bindungsfrist oder eine bewusst gewählte Exposition bestehen. Ein isolierter Fall liefert höchstens Hinweise; die angebotenen Übungsfälle benennen deshalb die entscheidenden Annahmen ausdrücklich.'])
 ]),
 S('moderate-adapt','Korrigieren und die Folgen begrenzen','a',[
  'Moderation versucht, einen Fehler selbst zu vermindern: eine Basisrate sichtbar machen, eine Schätzung unabhängig erstellen oder ein Gegenargument verpflichtend prüfen. Anpassung akzeptiert eine verbleibende Tendenz als Planungsbedingung und begrenzt ihre schädlichen Folgen, etwa durch eine vorab vereinbarte Kontrollregel.',
  X('Wissen allein verhindert den späteren Impuls nicht immer','Eine Kundin versteht den Nutzen der Streuung, möchte aber in jeder Krise aus Angst sämtliche Aktien verkaufen. Eine hohe Aktienquote wäre finanziell tragbar, wird emotional jedoch nicht durchgehalten.',[
   'Zuerst werden Verständnis, reale Verpflichtungen und die konkrete Verlustreaktion geklärt. Eine sachliche Erklärung kann helfen, ersetzt aber keine tatsächlich getragene Entscheidung.',
   'Eine im gemeinsamen Auftrag festgelegte niedrigere Quote oder ein klarer Überprüfungsprozess kann einen späteren vollständigen Planabbruch vermeiden helfen. Dabei bleiben Zielerreichung und Kosten zu prüfen; die Anpassung ist keine Erlaubnis, notwendige Zahlungen zu gefährden.'
  ],'Die passende Antwort hängt von Mechanismus, Schwere und wirtschaftlichen Folgen ab. Nicht jede Verzerrung wird durch ein einziges Gespräch beseitigt.')
 ]),
 S('conservatism','Conservatism: zu wenig auf neue relevante Information reagieren','b',[
  'Conservatism Bias bezeichnet hier das zu starke Festhalten an einer bisherigen Überzeugung trotz neuer, für die Einschätzung relevanter Information. Gemeint ist keine konservative niedrige Aktienquote. Der Fehler liegt in der unzureichenden Aktualisierung, nicht in einem bestimmten Risikostil.',
  X('Eine alte Absatzannahme bleibt trotz neuer Daten stehen','Ein Analyst erwartet unveränderte Stückzahlen. Ein verlässlicher neuer Datensatz zeigt im eigenen Szenario einen wesentlichen dauerhaft verlorenen Kunden; alle übrigen Annahmen bleiben gleich.',[
   'Der Kundenverlust muss in die Szenarien und die Bewertung eingehen. Eine kleinere Reaktion kann begründet sein, wenn die neue Information unsicher oder bereits erwartet war; diese Begründung muss konkret vorliegen.',
   'Den Verlust allein deshalb zu ignorieren, weil die alte Planung lange verwendet wurde, schützt die frühere Überzeugung statt ihre Evidenz. Hilfreich sind dokumentierte Auslöser für eine Modellaktualisierung.'
  ],'Das Gegenmittel ist ein nachvollziehbarer Abgleich alter und neuer Information, kein automatischer Aktionismus bei jeder Nachricht.')
 ]),
 S('confirmation','Confirmation: passende Belege suchen und Gegenbelege aussortieren','b',[
  'Confirmation Bias beeinflusst, welche Information gesucht, gelesen, erinnert oder als glaubwürdig behandelt wird. Wer bereits optimistisch ist, kann positive Interviews sammeln und gleichwertige negative Daten ohne Untersuchung verwerfen. So sieht die Beleglage durch den eigenen Auswahlprozess überzeugender aus.',
  X('Zwei gleich zuverlässige Quellen, nur eine wird akzeptiert','Ein Fondsmanager hält eine Wachstumsthese. Er übernimmt eine positive Kundenbefragung, verwirft aber eine methodisch gleichwertige negative Befragung allein, weil sie seiner These widerspricht.',[
   'Die Qualität beider Quellen wird mit denselben Kriterien geprüft. Eine Quelle darf wegen konkreter methodischer Schwächen weniger Gewicht erhalten, nicht allein wegen ihres unerwünschten Ergebnisses.',
   'Ein unabhängiger Gegenprüfer, eine dokumentierte Gegenhypothese und vorab genannte Widerlegungskriterien machen einseitige Auswahl sichtbarer.'
  ],'Conservatism betrifft vor allem das Ausmaß der Aktualisierung; Confirmation betrifft insbesondere den selektiven Umgang mit Belegen.')
 ]),
 S('representativeness','Representativeness: Ähnlichkeit ersetzt keine Basisrate','b',[
  'Ein Fall wird einer vertrauten Kategorie zugeordnet und deren typische Geschichte als Wahrscheinlichkeit verwendet. Ein dynamischer Gründer kann etwa wie ein früherer erfolgreicher Unternehmer wirken. Diese Ähnlichkeit ersetzt weder die Häufigkeit erfolgreicher Vorhaben noch die konkreten Daten des neuen Geschäfts.',
  'Zwei verbreitete Varianten sind die Vernachlässigung von Basisraten und ein zu großes Vertrauen in kleine Stichproben. Drei gute Fondsjahre können ein Muster suggerieren, obwohl zufällige Schwankungen und die Auswahl vieler beobachteter Fonds zu berücksichtigen sind.',
  X('Eine gute Firma ist nicht automatisch eine günstig bewertete Aktie','Eine Gesellschaft hat starke Produkte und zufriedene Kunden. Ein Anleger schließt allein daraus auf eine besonders hohe künftige Aktienrendite.',[
   'Die wirtschaftliche Qualität kann den Unternehmenswert stützen. Der heutige Preis kann diese Qualität jedoch bereits enthalten oder übersteigen. Für die erwartete Rendite zählen Preis, künftige Zahlungen und Risiken zusammen.',
   'Die typische Erfolgsgeschichte wird daher durch eine konkrete Bewertung und geeignete Vergleichsfälle ergänzt. Der Schluss vom guten Unternehmen auf den sicheren guten Kauf wäre unvollständig.'
  ],'Die passende Vergleichsgruppe und der Preis sind zusätzliche Informationen, keine unnötigen Hindernisse der intuitiven Geschichte.')
 ]),
 S('bayes','Die Basisrate mit einer Häufigkeitstabelle sichtbar machen','b',[
  'Der folgende rein hypothetische Signaltest beschreibt keine handelbare Aktienprognose. H bezeichnet eine seltene Eigenschaft mit zwei Prozent Grundhäufigkeit. Ein positives Signal tritt bei H in achtzig Prozent der Fälle auf, ohne H aber ebenfalls in zehn Prozent.',
  F('P(H\\mid+)=\\frac{P(+\\mid H)P(H)}{P(+\\mid H)P(H)+P(+\\mid\\neg H)P(\\neg H)}','Die bedingte Trefferquote und die gesuchte Hypothesenwahrscheinlichkeit nach einem Signal haben verschiedene Bezugsgruppen. Beide möglichen Ursachen eines positiven Signals gehören in den Nenner.',[['H,\\neg H','Hypothese beziehungsweise ihr Gegenereignis.'],['+','Positives Signal.'],['P(A\\mid B)','Wahrscheinlichkeit des Ereignisses A unter der Bedingung B.'],['P(H),P(\\neg H)','Grundhäufigkeiten vor dem Signal; sie summieren sich auf eins.']]),
  X('80 Prozent Trefferquote werden zu rund 14 Prozent posteriorer Wahrscheinlichkeit','Von 10.000 vergleichbaren Fällen haben nach den Annahmen 200 die Eigenschaft H und 9.800 nicht. Die angegebenen Raten werden als exakte Modellhäufigkeiten verwendet.',[
   T(['Gruppe','Anzahl insgesamt','Positives Signal'],[['H','200','160'],['Nicht H','9800','980'],['Insgesamt','10000','1140']],'Die großen Grundgruppen können viele falsch positive Signale erzeugen, obwohl deren bedingte Quote nur zehn Prozent beträgt.'),
   F('P(H\\mid+)=\\frac{160}{160+980}=\\frac{8}{57}\\approx14{,}0351\\%','Gesucht ist der Anteil der H-Fälle unter allen positiven Signalen. Achtzig Prozent beziehen sich dagegen auf positive Signale innerhalb der viel kleineren H-Gruppe.',[['P(H\\mid+)','Wahrscheinlichkeit von H nach einem positiven Signal im vorausgesetzten Modell.']]),
   'Bei einer anderen Basisrate oder Signalqualität ändert sich das Ergebnis. Die Rechnung beweist keine zeitlich stabile Zuverlässigkeit realer Analystensignale.'
  ],'Die Umkehrung einer bedingten Wahrscheinlichkeit ist keine sprachliche Kleinigkeit, sondern eine andere Bezugsgruppe.'),
  chart('base-rate','Dasselbe Signal, andere Grundhäufigkeit','Eigene Signalannahmen: Achtzig Prozent der H-Fälle und zehn Prozent der Nicht-H-Fälle liefern ein positives Signal. Die Grundhäufigkeit wird variiert.','Die hinterher gesuchte Wahrscheinlichkeit hängt stark von der Ausgangshäufigkeit ab. Die waagerechten achtzig Prozent sind die konstante bedingte Trefferquote und gerade keine universelle Posteriorwahrscheinlichkeit.',[0,50],[0,100],'Grundhäufigkeit von H (%)','Wahrscheinlichkeit (%)',[{name:'H nach positivem Signal',points:grid(0,50,100,p=>100*(.8*p)/(.8*p+.1*(100-p)))},{name:'H vor dem Signal',points:[[0,0],[50,50]]},{name:'Bedingte Trefferquote des Signals',points:[[0,80],[50,80]]}])
 ]),
 S('control','Illusion of Control: Entscheidungsmacht mit Ergebnismacht verwechseln','b',[
  'Ein Anleger kann seine Order, Titelzahl und Einsatzhöhe beeinflussen. Daraus folgt keine Kontrolle über künftige Marktpreise. Die Illusion entsteht, wenn persönliche Beteiligung oder Vertrautheit als Macht über einen tatsächlich unsicheren äußeren Vorgang behandelt wird.',
  X('Selbst klicken verändert die Marktunsicherheit nicht','Ein Anleger glaubt, eine persönlich am Bildschirm eingegebene Order werde eher gewinnen als dieselbe wirtschaftliche Position über eine korrekt ausführende Automatik. Ausführungspreis, Gebühren und Zeitpunkt sind ausdrücklich gleich.',[
   'Unter den gegebenen Annahmen unterscheiden sich die wirtschaftlichen Positionen nicht. Die persönliche Eingabe gibt deshalb keinen zusätzlichen Einfluss auf den späteren Preisverlauf.',
   'Anders wäre eine reale Verbesserung der Ausführung, Kontrolle eines Limits oder Vermeidung eines Bedienfehlers. Diese tatsächliche Kontrolle ist vom behaupteten Einfluss auf die Marktrendite zu trennen.'
  ],'Eine Kontrollliste prüft reale Einflussmöglichkeiten und die verbleibenden externen Unsicherheiten.')
 ]),
 S('hindsight','Hindsight: nach dem Ereignis war es angeblich vorhersehbar','b',[
  'Nach Bekanntwerden des Ergebnisses wird die frühere Unsicherheit unterschätzt oder die eigene Erinnerung an die damalige Prognose verändert. Ein vorher nur eines von mehreren Szenarien erscheinender Ausgang wird nachträglich als offensichtlich dargestellt.',
  X('Eine frühere Wahrscheinlichkeit wird im Rückblick umgeschrieben','Ein Protokoll nennt für einen Abschwung eine Wahrscheinlichkeit von dreißig Prozent. Nach dessen Eintritt behauptet ein Analyst, er habe ihn sicher vorhergesagt.',[
   'Ein tatsächlich eingetretener Dreißig-Prozent-Fall macht die frühere Schätzung nicht automatisch falsch. Eine kalibrierte Prognose darf Ereignisse unter hundert Prozent enthalten, die gelegentlich eintreten.',
   'Das zeitgestempelte Protokoll verhindert das Umschreiben der eigenen damaligen Gewissheit. Für die Qualität der Wahrscheinlichkeiten braucht man zusätzlich geeignete wiederholte Vergleichsfälle.'
  ],'Hindsight verändert die Darstellung dessen, was vorher bekannt war. Ergebnisverzerrung beurteilt zusätzlich die Entscheidung allein nach ihrem Ausgang.'),
  D('Hilfsmittel',['Ein Entscheidungsjournal hält Prognose, Bandbreite, Gegenargumente und Auslöser der Aktualisierung vor dem Ergebnis fest. Die spätere Auswertung vergleicht diese Angaben mit den tatsächlich eingetretenen Daten, statt Erinnerungen als unveränderte Aufzeichnungen zu behandeln.'])
 ]),
 S('anchoring','Anchoring and Adjustment: ein irrelevanter Startwert bleibt zu wichtig','b',[
  'Ein früher Kaufpreis, ein Hochkurs oder die zuerst genannte Schätzung kann eine Bewertung verankern. Neue Information wird zwar berücksichtigt, aber die Anpassung vom Startwert ist unzureichend. Ein historischer Wert kann Information liefern; zum Bias wird sein unangemessenes Gewicht.',
  X('Der Kaufpreis erklärt nicht allein den heutigen Wert','Ein Anleger kaufte für 100 Euro. Nach einer dauerhaft veränderten Geschäftslage begründet eine aktuelle Analyse unter den angenommenen Szenarien einen Wert von 70. Er verlangt eine Bewertung nahe hundert allein, weil er dort gekauft hat.',[
   'Der frühere Kaufpreis beschreibt seinen historischen Kapitaleinsatz. Er ist kein zusätzlicher künftiger Zahlungsstrom des Unternehmens. Steuerfolgen oder konkrete Informationsgehalte des Preises müssten separat begründet werden.',
   'Eine unabhängig neu erstellte Bewertung und ein Vergleich mit den aktuellen Alternativen begrenzen die Bindung an den Anker. Verluste müssen dafür nicht geleugnet werden.'
  ],'Ein Anker ist der Startwert einer Beurteilung; Endowment Bias knüpft dagegen besonders an die eigene Eigentümerrolle an.')
 ]),
 S('mental','Mental Accounting: Teile getrennt statt den Gesamtzusammenhang bewerten','b',[
  'Geld oder Risiken werden gedanklich in getrennte Konten eingeteilt, deren Zusammenhänge dann vernachlässigt werden. Ein Bonus wird etwa leichter verspielt als derselbe Betrag aus dem regelmäßigen Einkommen, obwohl Verfügbarkeit und wirtschaftliche Folgen ausdrücklich identisch sind.',
  X('Ein sicherer und ein spekulativer Topf können dieselbe Gesamtexposition haben','Portfolio A hält hundert Euro in einem gemeinsamen Konto mit sechzig Euro Aktien und vierzig Euro Cash. Portfolio B hält sechzig Euro Aktien im Spielkonto und vierzig Euro Cash im Sicherheitskonto. Bestände, Kosten, Steuern und Rechte sind identisch.',[
   F('R_A=R_B=0{,}60R_E+0{,}40R_C','Das Umbenennen zweier identischer Bestände verändert deren gemeinsame Rendite nicht. Auch ein Verlust im Spielkonto ist ein Verlust des Gesamtvermögens.',[['R_A,R_B','Renditen der wirtschaftlich identischen Gesamtportfolios.'],['R_E,R_C','Aktien- beziehungsweise Cashrendite derselben Periode.']]),
   'Zielkonten können die Planung und Selbstkontrolle sinnvoll unterstützen. Sie werden erst dann problematisch, wenn die getrennte Darstellung gemeinsame Risiken oder tatsächlich finanzierbare Zahlungen verdeckt.'
  ],'Eine organisatorische Aufteilung ist nicht per se falsch. Die wirtschaftliche Gesamtrechnung bleibt notwendig.')
 ]),
 S('framing','Framing: dieselbe Entscheidung wird anders verpackt','b',[
  'Framing Bias liegt vor, wenn eine wirtschaftlich gleichbleibende Wahl allein durch ihre Darstellung anders beurteilt wird. Ein Verlust kann als verbleibendes Vermögen, eine Erfolgsquote als Fehlquote oder derselbe Zeitraum mit verschiedenen Ausgangspunkten beschrieben werden.',
  X('Zehn Euro Verlust oder neunzig Euro Restvermögen','Anfangsvermögen hundert Euro. Alternative A endet sicher bei neunzig; B endet mit gleicher Wahrscheinlichkeit bei achtzig oder hundert. Die Optionen werden einmal als Verluste und einmal als Restvermögen präsentiert. Kosten und Rechte bleiben gleich.',[
   F('E(W_A)=90,\\quad E(W_B)=0{,}5(80)+0{,}5(100)=90','Die gleiche Erwartung macht die Risiken nicht gleich. Entscheidend für den Framing-Test ist, dass jede konkrete Option in beiden Beschreibungen dieselben Endzustände besitzt.',[['W_A,W_B','Endvermögen der sicheren beziehungsweise unsicheren Alternative.'],['E','Erwartungswert unter den ausdrücklich gegebenen Wahrscheinlichkeiten.']]),
   'Ein Vergleich mit einer tatsächlich anderen Wahrscheinlichkeit oder Auszahlung wäre kein reiner Darstellungstest. Tabellen mit denselben Endwerten helfen, die wirtschaftliche Gleichheit zu erkennen.'
  ],'Nicht jede andere Reaktion beweist sofort einen Fehler; zuerst wird geprüft, ob alle wirtschaftlich relevanten Bedingungen wirklich unverändert sind.')
 ]),
 S('availability','Availability: leicht erinnerbar ist nicht automatisch häufig','b',[
  'Lebhafte Berichte, gerade erlebte Ereignisse oder vertraute Unternehmen werden leichter abgerufen. Daraus kann eine zu hohe eingeschätzte Wahrscheinlichkeit oder ein zu enger Suchraum entstehen. Das leicht verfügbare Beispiel wird mit der relevanten Grundgesamtheit verwechselt.',
  X('Ein spektakulärer Ausfall ersetzt keine Ausfallstatistik','Ein Anleger sieht mehrfach denselben großen Unternehmensausfall in den Nachrichten und schließt, die Ausfallwahrscheinlichkeit jeder gleich eingestuften Anleihe habe sich vervielfacht.',[
   'Die wiederholten Meldungen sind nicht mehrere unabhängige Ausfälle. Aktuelle relevante Marktdaten und gemeinsame wirtschaftliche Änderungen werden separat geprüft.',
   'Der einzelne Vorgang kann neue Information enthalten. Sein Nachrichtenumfang allein liefert aber weder den Nenner aller vergleichbaren Schuldner noch deren aktuelle bedingte Ausfallraten.'
  ],'Die Gegenprüfung sucht systematisch nach vergleichbaren Fällen und einer passenden Bezugsgruppe statt nur nach weiteren eindrucksvollen Geschichten.')
 ]),
 S('loss-aversion','Loss Aversion: Verluste relativ zum Bezugspunkt wiegen stärker','b',[
  'Verlustaversion beschreibt eine asymmetrische Bewertung gleich großer Gewinne und Verluste relativ zu einem Bezugspunkt. Sie ist von allgemeiner Risikoaversion zu unterscheiden. Risikoaversion betrifft die Präferenz zwischen unsicheren und passenden sicheren Ergebnissen; Verlustaversion betrifft insbesondere die zusätzliche negative Bedeutung des Unterschreitens eines Referenzwerts.',
  F('v(x)=\\begin{cases}\\sqrt{x},&x\\geq0\\\\-\\lambda\\sqrt{-x},&x<0\\end{cases},\\qquad\\lambda=2','Dies ist eine selbst gewählte illustrative Wertfunktion. Positive Veränderungen werden konkav, negative Veränderungen konvex und betragsmäßig stärker bewertet. Die Form ist keine geschätzte Kundenpräferenz und kein vollständiges Prospect-Theory-Modell.',[['x','Veränderung eines Eurobetrags relativ zum ausdrücklich genannten Bezugspunkt.'],['v(x)','Deskriptiver Bewertungsscore; keine Euroauszahlung und keine objektive Finanzrendite.'],['\\lambda','Hier selbst gewähltes positives Verlustgewicht zwei; für den Vergleich wird auch eins gezeigt.']]),
  X('Ein fairer Geld-Erwartungswert kann emotional unattraktiv sein','Ein eigener 50/50-Versuch gewinnt oder verliert hundert Euro relativ zum gleichen Bezugspunkt. Für diesen einzelnen Vergleich werden die gegebenen Wahrscheinlichkeiten unverändert als Gewichte verwendet.',[
   F('E(x)=0{,}5(100)+0{,}5(-100)=0,\\quad V=0{,}5v(100)+0{,}5v(-100)=-5','Der Geld-Erwartungswert ist null. Der eigene illustrative Score ist negativ, weil die gleich große Verlustseite das doppelte Gewicht besitzt.',[['E(x)','Erwartete Euroveränderung.'],['V','Gewichteter illustrativer Bewertungsscore unter den hier gegebenen gleichen Gewichten.'],['v','Im vorigen Block vollständig definierte eigene Wertfunktion mit Verlustgewicht zwei.']]),
   'Ein negativer Score ist keine objektiv verlorene Fünf-Euro-Zahlung. Vollständige deskriptive Modelle können zusätzlich nichtlineare Entscheidungsgewichte und weitere Referenzannahmen benötigen.'
  ],'Der Vergleich erklärt einen möglichen Mechanismus, ohne einer realen Person anhand einer Formel eine Präferenz zuzuschreiben.'),
  chart('value-function','Die Verlustseite verändern, die Gewinnseite festhalten','Eigene illustrative Wertfunktion: Quadratwurzel auf der Gewinnseite; auf der Verlustseite minus Verlustgewicht mal Quadratwurzel des Verlustbetrags. Keine empirische Parameterschätzung.','Bei gleicher positiver Veränderung liegen beide Kurven übereinander. Auf der Verlustseite verdoppelt das Verlustgewicht den negativen Score. Die Achse zeigt Bewertungseinheiten und keine Rendite.',[-100,100],[-22,12],'Veränderung zum Bezugspunkt (EUR)','Illustrativer Bewertungsscore',[{name:'Verlustgewicht 1',points:grid(-100,100,100,x=>value(x,1))},{name:'Verlustgewicht 2',points:grid(-100,100,100,x=>value(x,2))}])
 ]),
 S('reference','Derselbe Endwert, ein anderer Bezugspunkt','b',[
  'Der Referenzwert bestimmt, was überhaupt als Gewinn oder Verlust wahrgenommen wird. Anfangsvermögen, historischer Höchststand oder eine erwartete Auszahlung können unterschiedliche mentale Bezugspunkte sein. Sie sind nicht automatisch passende wirtschaftliche Zielwerte.',
  X('Die sichere Neunzig und die unsicheren Achtzig/Hundert erneut betrachten','Es gelten genau die Endwerte des Framing-Falls. Für die eigene Wertfunktion mit Verlustgewicht zwei werden zwei verschiedene mentale Referenzen betrachtet. Dies ist eine Darstellung des Modells, keine universelle Verhaltenserwartung.',[
   F('V_A(100)=v(-10)=-2\\sqrt{10}\\approx-6{,}3246,\\quad V_B(100)=0{,}5v(-20)+0{,}5v(0)=-\\sqrt{20}\\approx-4{,}4721','Relativ zu hundert liegen beide Optionen auf der Verlustseite. Im eigenen konvexen Verlustbereich erhält die unsichere Wahl den höheren, weniger negativen Score.',[['V_A(c),V_B(c)','Bewertungsscores der beiden Optionen relativ zum Referenzbetrag c.'],['v','Eigene Wertfunktion aus dem vorigen Abschnitt.']]),
   F('V_A(80)=v(10)=\\sqrt{10}\\approx3{,}1623,\\quad V_B(80)=0{,}5v(0)+0{,}5v(20)=0{,}5\\sqrt{20}\\approx2{,}2361','Relativ zu achtzig liegen die Veränderungen auf der Gewinnseite. Dort bewertet dieselbe eigene konkave Funktion die sichere Wahl höher.',[['V_A(c),V_B(c)','Scores der unveränderten Endwertoptionen beim jeweils genannten mentalen Bezugspunkt.'],['v','Eigene illustrative Wertfunktion; gleiche Wahrscheinlichkeiten bleiben als Gewichte erhalten.']]),
   'Die Endvermögen haben sich nicht verändert. Ein Auftrag zur sicheren Zahlung oder eine finanzielle Verlustgrenze muss deshalb zusätzlich in tatsächlichen Euro-Endwerten geprüft werden.'
  ],'Referenzabhängigkeit kann Risikosuche in Verlustsituationen und Vorsicht bei Gewinnsituationen gemeinsam verständlich machen. Sie bedeutet nicht, dass Verlustaverse in jeder Situation risikoavers handeln.')
 ]),
 S('disposition','Disposition Effect: Gewinner verkaufen, Verlierer aussitzen','b',[
  'Eine häufig diskutierte Folge ist die Neigung, Gewinne früh zu realisieren und Verluste lange festzuhalten. Der Verkauf einer Verlustposition würde das negative Ergebnis psychologisch anerkennen; eine Gewinnerposition erlaubt dagegen das positive Gefühl einer bestätigten Entscheidung.',
  X('Der historische Einstand wird von heutigen Alternativen getrennt','Zwei wirtschaftlich vergleichbare Positionen stehen heute jeweils bei achtzig Euro. A wurde für hundert gekauft, B für sechzig. Für den Vergleich gelten dieselbe künftige Verteilung, gleiche Kosten und ausdrücklich keine Steuer- oder Rechtsunterschiede.',[
   'Allein die Hoffnung, A müsse erst wieder seinen Einstand erreichen, ist keine zusätzliche erwartete Zahlung. Der historische Gewinn bei B beweist ebenso wenig, dass diese Position jetzt weniger geeignet ist.',
   'Eine Gegenfrage lautet, welche der Positionen unter den heutigen Daten neu gekauft würde. Ein Verkauf kann gleichwohl wegen einer echten Übergewichtung oder einer tatsächlichen Steuerwirkung begründet sein; diese Gründe sind hier ausdrücklich ausgeschlossen oder gesondert zu nennen.'
  ],'Nicht jedes Halten eines Verlierers oder jeder Gewinnverkauf ist ein Bias. Entscheidend sind die angegebenen Gründe und der heutige Gesamtauftrag.')
 ]),
 S('overconfidence','Overconfidence: eigene Kenntnis und Präzision überschätzen','b',[
  'Übermäßiges Vertrauen kann die eigene Fähigkeit, Informationsqualität oder Vorhersagegenauigkeit betreffen. Ein Analyst kann sich für besser als vergleichbare Fachleute halten, seine Fehlerrate unterschätzen oder viel zu enge Prognoseintervalle angeben. Selbstbewusstsein allein ist noch kein Fehler; es geht um eine nicht durch Evidenz gedeckte Überschätzung.',
  X('Ein enges Intervall ist nicht automatisch ein gutes Intervall','Ein Prognostiker nennt regelmäßig Intervalle mit behaupteter Abdeckung von neunzig Prozent. Bei hundert geeigneten, vorab vergleichbar abgegrenzten Prognosen enthalten nur sechzig den tatsächlich späteren Wert.',[
   F('\\widehat c=60/100=60\\%','Die beobachtete Abdeckung liegt weit unter der genannten neunzig Prozent. Stichprobenunsicherheit und Abhängigkeit der Fälle sind zusätzlich zu beachten; der Unterschied ist zunächst ein Anlass zur Kalibrierungsprüfung.',[['\\widehat c','In dieser vorgegebenen Stichprobe beobachteter Anteil korrekt abgedeckter Ergebnisse.']]),
   'Wer eigene Erfolge ausschließlich Können und Misserfolge ausschließlich Pech zuschreibt, kann das Selbstbild weiter verstärken. Ein Journal erfasst deshalb alle vorher definierten Fälle, auch die misslungenen.'
  ],'Die CFA-Gruppierung behandelt Overconfidence überwiegend als emotionalen Bias. Ihre konkreten Erscheinungen können zugleich Denk- und Informationsfehler enthalten.')
 ]),
 S('overtrading','Eine zusätzliche Meinung muss auch zusätzliche Kosten verdienen','b',[
  'Übermäßiges Vertrauen kann zu zu vielen Transaktionen, konzentrierten Wetten und unterschätztem Risiko führen. Handel kann jedoch auch rational sein, etwa zur Liquiditätsbeschaffung, Risikosteuerung oder Umsetzung neuer belastbarer Information. Die Anzahl der Trades allein diagnostiziert keine Überkonfidenz.',
  F('1+R_n=(1+R_g)(1-c)^k','Im eigenen Jahresvergleich werden k zusätzliche vollständige Umschichtungen jeweils mit Kostenanteil c auf den dann umgeschichteten gesamten Bestand belastet. Der identische Bruttoanlagefaktor wird ausdrücklich festgehalten.',[['R_n,R_g','Jährliche Nettorendite nach diesen zusätzlichen Kosten beziehungsweise festgehaltener Bruttoertrag.'],['c','Kostenanteil pro ausdrücklich vollständig umgeschichteter Runde; hier 0,4 Prozent.'],['k','Zahl zusätzlicher Runden; in der Grafik nichtnegative ganze Zahl.']]),
  X('Identische Bruttoleistung, verschiedene Handelsintensität','Beide eigenen Strategien verdienen sechs Prozent brutto. A führt keine zusätzlichen Runden aus, B zehn mit je 0,4 Prozent proportionalen Kosten. Keine Steuern oder weiteren Kosten.',[
   F('R_{n,B}=1{,}06(0{,}996)^{10}-1\\approx1{,}8355\\%','Die Kosten wirken wiederholt auf den jeweiligen Bestand. Zehn mal 0,4 Prozent ist nur eine Näherung des Kostenfaktors und darf nicht mit einer anderen Gebührenbasis verwechselt werden.',[['R_{n,B}','Jahresertrag der zweiten Strategie nach genau diesen zusätzlichen Umschichtungskosten.']]),
   'Eine Strategie mit zusätzlichem Informationsnutzen könnte auch einen anderen Bruttoertrag liefern. Dieser Nutzen müsste die Kosten und zusätzlichen Risiken rechtfertigen; er wird im kontrollierten Vergleich ausdrücklich nicht unterstellt.'
  ],'Eine richtige Bruttomeinung ist noch kein Nachweis eines vorteilhaften Nettohandels.'),
  chart('trading-cost','Nur die Zahl der zusätzlichen Handelsrunden verändern','Eigene Jahresrechnung: sechs Prozent identischer Bruttoertrag, 0,4 Prozent Kosten je vollständiger zusätzlicher Runde, keine Steuer.','Mit mehr Runden sinkt bei identischer Bruttoleistung der Nettoertrag. Dies isoliert Kosten und beweist nicht, dass jede reale Umschichtung unnütz ist.',[0,20],[-3,7],'Zusätzliche vollständige Runden','Jährliche Nettorendite (%)',[{name:'Netto nach den zusätzlichen Kosten',points:grid(0,20,20,k=>(1.06*.996**k-1)*100)},{name:'Festgehaltener Bruttoertrag',points:[[0,6],[20,6]]}]),
  D('Was eine historische Studie zeigen kann',['Barber und Odean untersuchten US-Brokerkonten aus den 1990er-Jahren und fanden in ihrer Stichprobe einen Zusammenhang zwischen hoher Handelsintensität und schwächerer Nettoleistung. Das ist keine Aussage, dass jeder heutige aktive Anleger denselben Ertrag erzielt oder jede Transaktion schädlich ist. Stichprobe, Zeitraum, Kosten und mögliche konkurrierende Erklärungen bleiben relevant.'])
 ]),
 S('self-control','Self-control Bias: einen eigenen Langfristplan wiederholt unterlaufen','b',[
  'Kurzfristiger Konsum oder ein Impuls kann die zuvor ausdrücklich befürwortete langfristige Finanzierung verdrängen. Gemeint ist ein wiederkehrender Widerspruch zu den eigenen geklärten Zielen, nicht die Behauptung, jede heutige Ausgabe sei unvernünftig.',
  X('Zehn Jahre später anfangen, bei sonst gleichen Annahmen','Zwei fiktive Pläne zahlen je tausend Euro am Ende jedes Beitragsjahres bei konstant sechs Prozent netto. A zahlt dreißig Jahre, B erst nach zehn Jahren und dann zwanzig Jahre bis zum selben Endtermin. Kein Startkapital.',[
   F('FV_A=1000\\frac{1{,}06^{30}-1}{0{,}06}\\approx79\\,058{,}19,\\quad FV_B=1000\\frac{1{,}06^{20}-1}{0{,}06}\\approx36\\,785{,}59','B fehlen nicht nur zehn Beiträge, sondern auch deren längere Verzinsung. Der gleiche Endtermin macht den Zeitunterschied sichtbar.',[['FV_A,FV_B','Nominales Endvermögen der beiden ausdrücklich datierten Beitragspläne.']]),
   'Automatisierte Beiträge, ein Notfallpuffer und ein realistisches Ausgabenbudget können die Umsetzung unterstützen. Eine ungeplante echte Notlage oder teure Schuldentilgung kann dagegen einen sachlichen Grund liefern, den Plan bewusst zu ändern.'
  ],'Selbstbindung soll einen tragfähigen eigenen Plan unterstützen und darf notwendige Liquidität nicht unbemerkt aufzehren.'),
  chart('saving-delay','Fehlende frühe Beiträge fehlen auch beim späteren Zinseszins','Eigene Jahresendbeiträge von tausend Euro, sechs Prozent konstante Nettorendite, kein Startkapital. Die zweite Variante lässt die ersten zehn Beiträge aus.','Bis zum gemeinsamen Ende von Jahr dreißig sammelt der spätere Plan nur zwanzig Beiträge. Die Kurven sind ein deterministischer Vergleich und keine sichere Marktrendite.',[0,30],[0,85],'Jahr seit Beginn des ersten Plans','Vermögen (Tsd. EUR)',[{name:'Beiträge ab Jahr 1',points:grid(0,30,30,n=>saving(n)/1000)},{name:'Beiträge erst ab Jahr 11',points:grid(0,30,30,n=>saving(n,10)/1000)}])
 ]),
 S('status-quo','Status Quo: unverändert bleibt ohne Prüfung die bevorzugte Option','b',[
  'Die bestehende Aufteilung wird allein deshalb bevorzugt, weil sie bereits besteht oder als Standard voreingestellt ist. Ein sinnvoller Default kann die Planung unterstützen; ein Vergleich wird problematisch, wenn eine inzwischen ungeeignete Vorgabe ohne sachliche Prüfung fortgeschrieben wird.',
  X('Ein altes Arbeitgeberdepot bleibt nach einer wesentlichen Änderung unverändert','Nach einer Unternehmensfusion liegt ein sehr großer Anteil des gesamten frei verfügbaren Vermögens bei einem Arbeitgeber. Die vorher festgelegte Konzentrationsgrenze wird überschritten. Der Anleger prüft keine Alternative, allein weil die alte Aufteilung immer so war.',[
   'Zuerst werden Grenze, Steuern, Handelbarkeit und tatsächliche Änderungsmöglichkeiten geprüft. Der neue wirtschaftliche Gesamtbestand ist nicht automatisch mit dem früheren vereinbar.',
   'Ein fest terminierter Review mit dokumentierter aktiver Entscheidung kann die reine Trägheit aufbrechen. Nicht handeln kann nach dieser Prüfung trotzdem sinnvoll sein, wenn konkrete Kosten oder rechtliche Bindungen es rechtfertigen.'
  ],'Das Unterlassen einer Transaktion ist nicht an sich falsch; die ungeprüfte Bevorzugung des Bestehenden ist der entscheidende Mechanismus.')
 ]),
 S('endowment','Endowment: Eigentum allein erhöht die eigene Wertschätzung','b',[
  'Ein bereits besessener Gegenstand oder Vermögenswert wird höher bewertet als derselbe Wert als noch nicht erworbene Alternative. Der Unterschied kann sich als hohe Verkaufsforderung bei zugleich deutlich niedrigerer Kaufbereitschaft zeigen.',
  X('Geerbt oder zum aktuellen Preis neu erwerben?','Eine geerbte Aktie steht bei achtzig Euro. Der Eigentümer würde einen identischen zusätzlichen Anteil für achtzig nicht kaufen, fordert aber allein wegen der eigenen Eigentümerrolle hundert zum Verkauf. Kosten, Steuern, besondere Rechte und Informationsunterschiede sind ausdrücklich ausgeschlossen.',[
   'Der isolierte Rollenwechsel verändert hier keine künftige Zahlung. Die abweichende Bewertung wird deshalb gegen den benannten Eigentumseffekt geprüft.',
   'Ein realer Unterschied zwischen Kauf- und Verkaufsbereitschaft kann andere Gründe haben, etwa Transaktionskosten oder unterschiedliche finanzielle Ressourcen. Die Diagnose gilt nicht ohne die ausdrücklich kontrollierten Bedingungen.'
  ],'Einstandspreis als Startwert legt Anchoring nahe; die bloße Eigentümerrolle legt Endowment nahe. Beide können im selben Fall auftreten.')
 ]),
 S('regret','Regret Aversion: späteres Bedauern beeinflusst die heutige Wahl','b',[
  'Ein Anleger kann Entscheidungen vermeiden oder populären Anlagen folgen, um sich später nicht persönlich verantwortlich zu fühlen. Sowohl ein als falsch erlebter Kauf als auch eine verpasste Chance können Bedauern auslösen. Dadurch ist Regret Aversion nicht einfach gleichbedeutend mit jeder Verlustfurcht.',
  X('Die vertraute Mehrheit als Schutz vor persönlicher Verantwortung','Ein Anleger hält eine ungeeignete Konzentration allein deshalb, weil viele Bekannte dieselbe Position haben und er einen individuellen Verkauf später bereuen könnte. Die bekannten Grenzen und die wirtschaftlichen Erwartungen haben sich nicht geändert.',[
   'Die Zustimmung der Gruppe macht die gemeinsame Position nicht weniger konzentriert. Für den Auftrag zählen Risiko, Zahlungsbedarf und zulässige Alternativen weiterhin.',
   'Ein vorab vereinbarter Entscheidungsprozess und die dokumentierte Abwägung verschiedener Zustände können das spätere Bedauern besser einordnen. Die Absicht, jedes mögliche Bedauern vollständig auszuschließen, ist bei unsicheren Ergebnissen nicht erfüllbar.'
  ],'Status Quo betont das Beibehalten des Bestehenden; Regret Aversion betont die antizipierte emotionale Bewertung einer später als falsch empfundenen Entscheidung.')
 ]),
 S('comparisons','Benachbarte Fehler anhand der entscheidenden Tatsache unterscheiden','a b',[
  T(['Vergleich','Entscheidende Frage','Eigene Trennlinie'],[['Conservatism / Confirmation','Wird vorhandene neue Information zu wenig gewichtet oder wird sie vorher selektiert?','Unzureichende Aktualisierung gegenüber einseitiger Belegauswahl'],['Representativeness / Availability','Wird eine ähnliche Kategorie überschätzt oder die leichte Erinnerung mit Häufigkeit verwechselt?','Erfolgsgeschichte gegenüber Nachrichtenpräsenz'],['Anchoring / Endowment','Wirkt der Startwert oder vor allem die Eigentümerrolle?','Alter Einstand gegenüber Besitz desselben aktuellen Anspruchs'],['Mental Accounting / Framing','Werden Teile getrennt beurteilt oder dieselben Optionen anders präsentiert?','Gedankliche Konten gegenüber Entscheidungsdarstellung'],['Illusion of Control / Overconfidence','Wird tatsächlicher Einfluss oder die eigene Fähigkeit überschätzt?','Behauptete Ergebniskontrolle gegenüber überschätzter Kenntnis oder Präzision'],['Status Quo / Regret Aversion','Ist die bestehende Option ungeprüfter Default oder wird späteres Bedauern vermieden?','Trägheit gegenüber antizipierter Reue'],['Loss Aversion / Risk Aversion','Wirkt die Verlustseite relativ zum Referenzwert stärker oder die Unsicherheit insgesamt?','Asymmetrie am Bezugspunkt gegenüber Präferenz für eine geeignete sichere Alternative']],'Die Mechanismen können gleichzeitig vorliegen. In einer Einzelauswahlfrage entscheidet die besonders ausdrücklich genannte Tatsache.'),
  'Ein Etikett ersetzt keine begründete Ableitung. Eine gute Antwort nennt die beobachtete Handlung, die dazu passende Verzerrung, ihre wirtschaftliche Folge und eine gezielte Gegenmaßnahme.'
 ]),
 S('market','Vom individuellen Fehler zum möglichen Marktmuster','c',[
  'Ein individueller Fehler muss sich nicht unverändert im Marktpreis zeigen. Andere Anleger können gegenhalten; Informationsverteilung, Kapital, Risiken und Handelsregeln beeinflussen das gemeinsame Ergebnis. Behavioral Finance untersucht mögliche Mechanismen solcher aggregierten Abweichungen.',
  'Ein Anomaliemuster ist zunächst ein Muster relativ zu einem betrachteten Erklärungsmodell. Wenn eine Strategie einen ungewöhnlichen Ertrag zeigt, können falsche Risikomessung, Datenauswahl, Zufall, Handelskosten oder tatsächlich verzerrte Erwartungen konkurrierende Erklärungen sein. Die Beobachtung allein trennt diese Möglichkeiten nicht vollständig.',
  D('Gemeinsame Hypothesenprüfung',['Ein Test von Marktineffizienz verwendet zugleich ein Modell für angemessene erwartete Erträge oder Risiken. Eine Abweichung kann an der Effizienzannahme, am Bewertungsmodell oder an beiden liegen. Daher ist eine scheinbar hohe historische Rendite kein isolierter Beweis psychologischer Fehlbewertung.'])
 ]),
 S('underreaction','Langsame Anpassung und mögliche Fortsetzung von Preisbewegungen','c',[
  'Wenn neue relevante Information zu langsam verarbeitet oder zu wenig gewichtet wird, kann die Anpassung über mehrere Beobachtungszeitpunkte weiterlaufen. Das liefert eine mögliche Erklärung für Fortsetzungsmuster. Es ist keine Behauptung, dass jede positive Rendite eine weitere positive Rendite verursacht.',
  F('P_{t+1}=P_t+\\kappa(V-P_t),\\quad 0<\\kappa\\leq1','Dieses eigene stilisierte Anpassungsmodell schließt in jeder Periode einen festen Anteil der Lücke zu einer konstanten Modellreferenz. Die Referenz ist nur im Modell vorgegeben, nicht als tatsächlich bekannter Marktwert bewiesen.',[['P_t,P_{t+1}','Modellpreise an aufeinanderfolgenden diskreten Beobachtungszeitpunkten.'],['V','Konstant gesetzte Modellreferenz, hier 120 Euro.'],['\\kappa','Anteil der verbleibenden Lücke, der pro Modellschritt geschlossen wird.'],['t','Diskreter Modellzeitpunkt; keine feste reale Tageslänge.']]),
  X('Dieselbe Referenz, langsame statt sofortige Anpassung','Der Modellpreis startet bei hundert Euro, die neue feste Referenz bei 120. Bei Anpassungsanteil 0,5 wird zunächst die halbe Lücke geschlossen.',[
   F('P_1=100+0{,}5(120-100)=110,\\quad P_2=110+0{,}5(120-110)=115','Jeder Schritt bezieht sich auf die verbleibende Lücke. Der unveränderte Modellanker wird nicht jedes Mal als neue Nachricht interpretiert.',[['P_1,P_2','Erste und zweite Modellpreisbeobachtung nach dem Start.']]),
   'Ein realer Anleger kennt den wahren Vergleichswert nicht mit dieser Sicherheit. Neue Unternehmensdaten, Finanzierungskosten und Risiken können den tatsächlich angemessenen Wert während der Anpassung verändern.'
  ],'Das Modell illustriert einen möglichen Anpassungsweg. Seine vorhersehbare Kurve ist keine empirisch nachgewiesene Handelschance.')
 ]),
 S('overreaction','Extrapolation und Rückkopplung können über das Ziel hinausschießen','c',[
  'Anleger können eine kurze Erfolgsserie zu weit fortschreiben oder steigende Preise selbst als zusätzliche Bestätigung ihrer Geschichte behandeln. Käufe verstärken dann die jüngste Bewegung. Eine spätere Korrektur kann folgen, ist aber weder zeitlich noch dem Umfang nach garantiert.',
  F('P_{t+1}=P_t+\\kappa(V-P_t)+\\gamma(P_t-P_{t-1})','Die eigene Erweiterung ergänzt den Lückenschluss um einen Term, der die letzte Preisänderung fortschreibt. Sie ist ein veranschaulichender Mechanismus, kein geschätztes Preisgesetz.',[['P_{t-1},P_t,P_{t+1}','Modellpreise an drei aufeinanderfolgenden Zeitpunkten.'],['V','Hier konstante Modellreferenz 120 Euro.'],['\\kappa','Hier gewählter Anpassungsanteil 0,4.'],['\\gamma','Hier gewähltes Gewicht der vorigen Preisänderung 0,6.'],['t','Diskreter Modellzeitpunkt.']]),
  X('Mit derselben Referenz erst darüber und später zurück','Eigener Startpfad P0 gleich hundert, P1 gleich 108; danach gelten die obigen Parameter. Es werden keine neuen Cashflowinformationen unterstellt.',[
   F('P_2=108+0{,}4(120-108)+0{,}6(108-100)=117{,}6','Der Lückenschluss und das Fortschreiben des vorherigen Anstiegs wirken gemeinsam.',[['P_2','Zweiter Folgemodellpreis in Euro.']]),
   F('P_3=117{,}6+0{,}4(120-117{,}6)+0{,}6(117{,}6-108)=124{,}32','Die vorherige Aufwärtsbewegung trägt die nächste Beobachtung über die unveränderte Referenz hinaus.',[['P_3','Dritter Folgemodellpreis in Euro.']]),
   'Die spätere Dämpfung in genau dieser Parameterwahl ist eine Eigenschaft der eigenen Gleichung. Andere Parameter oder neue Referenzwerte können andere Verläufe erzeugen; eine reale Fehlbewertung muss deshalb nicht kurzfristig verschwinden.'
  ],'Fortsetzung und Umkehr können durch unterschiedliche Reaktionen auf Information entstehen. Ein nachträglich passender Erzählverlauf ist noch kein unabhängiger Beweis der Ursache.'),
  chart('price-adjustment','Langsame Anpassung und Überschießen im ausdrücklich eigenen Modell','Feste Referenz 120 Euro. Vergleich: halber Lückenschluss ohne Rückkopplung oder Anpassung 0,4 mit Fortschreibung 0,6 der letzten Preisänderung; Startwerte 100 und 108 für den zweiten Pfad.','Der erste Pfad nähert sich von unten. Der zweite überschießt zeitweise und schwingt gedämpft um die Referenz. Die vorgegebene Referenz und Parameter sind Annahmen und keine beobachtete sichere Fehlbewertung.',[0,10],[95,130],'Diskreter Modellzeitpunkt','Modellpreis (EUR)',[{name:'Langsame Anpassung ohne Rückkopplung',points:grid(0,10,10,t=>120-20*.5**t)},{name:'Anpassung mit Rückkopplung',points:grid(0,10,10,t=>feedback(t))},{name:'Feste Modellreferenz',points:[[0,120],[10,120]]}])
 ]),
 S('herding','Gleichgerichtete Entscheidungen sind nicht immer irrationale Herde','c',[
  'Viele Anleger können dieselbe Anlage aus derselben Information heraus rational wählen. Gleichgerichtetes Verhalten kann aber auch aus sozialer Bestätigung, Karriereanreizen, Angst vor abweichendem Bedauern oder dem Nachahmen vermeintlich besser Informierter entstehen.',
  X('Der Benchmarkvergleich verändert den persönlichen Anreiz','Ein Manager hält eine Position für teuer, fürchtet aber, bei weiter steigenden Preisen kurzfristig gegenüber Konkurrenten schlecht auszusehen. Sein Kapital kann bei Zwischenverlusten abgezogen werden.',[
   'Die persönliche oder vertragliche Bewertungsperiode kann vom Zeitraum bis zur möglichen Korrektur abweichen. Der Manager kann deshalb ein Risiko empfinden, das eine einfache Aussage über langfristigen Wert nicht abbildet.',
   'Das erklärt einen möglichen Anreiz, beweist aber weder die ursprüngliche Fehlbewertung noch eine unvermeidliche Blase. Abweichende Informationen und tatsächliche Risikoprämien müssen als Alternativen geprüft werden.'
  ],'Ein Marktmechanismus wird aus Informationen, Anreizen und Finanzierung erklärt, statt aus vielen ähnlichen Trades direkt auf einen einzigen Bias zu schließen.')
 ]),
 S('limits-arbitrage','Warum ein vermeintlich falscher Preis bestehen bleiben kann','c',[
  'Gegen eine vermutete Fehlbewertung zu handeln kann Fundamentalrisiko, weitere Preisabweichung, Leihkosten, Rückrufrisiko, Spannen und Finanzierungsbedarf auslösen. Eine ungedeckte oder nur statistisch ähnliche Gegenposition ist nicht dasselbe wie eine risikolose zustandsweise Replikation.',
  X('Die Finanzierung kann vor der erhofften Korrektur scheitern','Ein eigener vereinfachter Leerverkauf startet bei hundert Euro mit einem geliehenen Anteil. Hundert Verkaufserlös und fünfzig eigene Euro bleiben unverzinst als Cash hinterlegt. Vertraglich angenommene Maintenance-Anforderung: dreißig Prozent des aktuellen Aktienpreises. Keine Leihgebühren oder weiteren Positionen.',[
   F('E(P)=150-P,\\quad M(P)=0{,}30P','Der steigende Kurs vergrößert den Wert der Rückgabeverpflichtung und gleichzeitig die fiktive vorgeschriebene Deckung. Das frei verbleibende Eigenkapital sinkt.',[['P','Aktueller Aktienkurs in Euro für den einen geliehenen Anteil.'],['E(P)','Eigenkapital der beschriebenen isolierten Cash-und-Short-Position.'],['M(P)','Hier ausdrücklich vertraglich angenommene Maintenance-Mindestdeckung.']]),
   F('150-P=0{,}30P\\Rightarrow P=150/1{,}30\\approx115{,}3846','Oberhalb dieser Grenze unterschreitet das Eigenkapital unter den angenommenen Regeln die Mindestdeckung. Die Zahl ist keine allgemeingültige Broker- oder Rechtsvorschrift.',[['P','Aktienpreis, bei dem die zwei Modellbeträge genau gleich sind.']]),
   F('P=130:\\quad E=20,\\quad M=39,\\quad M-E=19','Bei 130 Euro fehlen neunzehn Euro Deckung. Eine mögliche spätere Korrektur auf hundert stellt dieses Geld heute nicht bereit.',[['P','Angenommener Stresskurs in Euro.'],['E,M','Verbleibendes Eigenkapital und verlangte Modell-Mindestdeckung in Euro.']]),
   'Reale Verträge können weitere Sicherheiten, andere Bewertungsregeln, Zwangsschließung und zusätzliche Gebühren vorsehen. Die eigene Rechnung isoliert nur den Finanzierungsmechanismus.'
  ],'Ein richtiger langfristiger Verdacht kann unter ungünstigem Zwischenverlauf finanziell nicht durchhaltbar sein. Das ist ein Grund, vermutete Fehlbewertung von sicherer Arbitrage zu trennen.'),
  chart('short-funding','Zwischenzeitlicher Kursanstieg belastet den Gegenhandel','Eigene isolierte Shortposition: 150 Euro festes Cash, ein zurückzugebender Anteil, Mindestdeckung dreißig Prozent seines aktuellen Preises. Keine Verzinsung oder Leihgebühren.','Bei steigenden Preisen sinkt das Eigenkapital, während die Mindestdeckung steigt. Die Kurven schneiden sich bei rund 115,38 Euro. Eine spätere Konvergenz finanziert den heutigen Fehlbetrag nicht automatisch.',[80,140],[0,80],'Aktienpreis (EUR)','Eigenkapital oder Mindestdeckung (EUR)',[{name:'Eigenkapital der Shortposition',points:grid(80,140,60,p=>150-p)},{name:'Angenommene Mindestdeckung',points:grid(80,140,60,p=>.3*p)}])
 ]),
 S('evidence','Ein Muster sauber von Erklärung und Handelsnutzen trennen','c',[
  T(['Behauptung','Zusätzliche Prüfung','Was allein nicht reicht'],[['Eine Rendite ist ungewöhnlich','Risikomodell, Stichprobe, Mehrfachsuche und Datenqualität','Nur die beste rückblickend ausgewählte Strategie'],['Ein Bias ist die Ursache','Entscheidungsdaten und konkurrierende Erklärungen','Eine nachträglich passende Geschichte'],['Das Muster bleibt bestehen','Außerhalb der Auswahlstichprobe und unter neuen Marktbedingungen prüfen','Dieselben Daten mehrfach auswerten'],['Es lässt sich handeln','Spannen, Marktimpact, Steuer, Finanzierung und Verfügbarkeit einbeziehen','Eine Bruttokurve ohne tatsächlichen Zugang'],['Es ist Arbitrage','Alle Zustände, Zahlungszeitpunkte und Risiken abgleichen','Nur die Erwartung späterer Preisannäherung']],'Erklärungskraft und sicherer Nettohandel sind unterschiedliche Anforderungen.'),
  'Die Möglichkeit psychologischer Fehlentscheidungen rechtfertigt keine automatische Überlegenheit des eigenen Urteils. Auch derjenige, der einen Bias bei anderen erkennt, kann Overconfidence, Confirmation oder Hindsight unterliegen.'
 ]),
 S('decision-process','Aus einem Verdacht eine gezielte Gegenmaßnahme ableiten','a b c',[
  T(['Problem','Gezielte Maßnahme','Prüfung ihrer Grenze'],[['Basisrate ignoriert','Gemeinsame Häufigkeitstabelle und unabhängige Vergleichsgruppe','Die verwendeten Wahrscheinlichkeiten können selbst falsch oder instabil sein'],['These wird nur bestätigt','Vorab definierte Gegenhypothese und unabhängige Gegenprüfung','Eine Checkliste darf nicht bloß formal abgehakt werden'],['Startwert dominiert','Unabhängige aktuelle Bewertung vor Kenntnis des irrelevanten Ankers','Reale Information und Steuerfolgen dürfen nicht entfernt werden'],['Verluste werden ausgesessen','Heutige Alternativen und den Gesamtauftrag prüfen','Rationales Halten ist möglich; pauschales Verkaufen ist keine Lösung'],['Impulsive Umschichtungen','Vereinbarte Review- und Rebalancing-Regeln','Regeln müssen neue Verpflichtungen und echte Grenzverletzungen berücksichtigen'],['Langfristiges Sparen wird unterlaufen','Tragfähige automatisierte Beiträge und Reserve','Notwendige heutige Zahlungen bleiben vorrangige Planungsbedingungen']],'Die Gegenmaßnahme muss den konkreten Mechanismus treffen und ihre eigenen Kosten und Fehlerquellen berücksichtigen.'),
  D('Prüfungsfälle lösen',['Zuerst die besonders hervorgehobene Tatsache identifizieren: selektive Quelle, irrelevanter Anker, Eigentümerrolle, mentale Trennung oder antizipierte Reue. Dann den zugehörigen Mechanismus begründen. Wenn mehrere Biases plausibel sind, entscheidet bei einer Einzelauswahl die präziseste Zuordnung der genannten Tatsache; ein allgemeines Etikett ist meist weniger hilfreich.'])
 ]),
 S('calculator','Präferenzmodell und regelgebundene Umsetzung ausprobieren','a b',[
  'Der verknüpfte Nutzenrechner bewertet die Mischung einer riskanten Anlage mit Cash durch Mittelwert und Varianz. Er demonstriert eine besondere Risikoaversionsannahme und enthält keinen Verlustbezugspunkt. Er ist deshalb gerade kein Rechner für die hier gezeigte Verlustaversion und keine Diagnose einer Person.',
  'Im zweiten Rechner verändern unterschiedliche Aktien- und Anleiherenditen die tatsächliche Quote ohne Handel. Eine vorher vereinbarte Rebalancing-Regel kann den nachfolgenden Entscheidungsprozess strukturieren. Der Rechner zeigt nur die Drift; er führt die Bandregel, Steuern und Transaktionen nicht automatisch aus.',
  D('Gezielter Vergleich',['Halte im Nutzenrechner Rendite und Risiko fest und ändere nur die Risikoaversion. Vergleiche das Ergebnis mit den zwei unveränderten Endwertoptionen aus dem Referenzfall: Dort verändert die mentale Referenz die illustrative Bewertung, während hier der Rechner ausdrücklich keine solche Referenz besitzt. Unterschiedliche Modelle dürfen nicht unter demselben Begriff unbemerkt ausgetauscht werden.'])
 ]),
 S('review','Verständnisfragen: Mechanismus, Rechnung und Gegenbeispiel','a b c',[
  ...[
   ['Warum beweist eine schlechte Rendite keinen bestimmten Bias?','Ein sinnvoller unsicherer Beschluss kann ungünstig ausgehen. Für die Zuordnung braucht man den damaligen Entscheidungsweg und Informationen; ein nachträgliches Ergebnis allein identifiziert keine psychologische Ursache.'],
   ['Was unterscheidet kognitive und emotionale Verzerrungen?','Kognitive Fehler betreffen vor allem Schlussfolgern, Information und Erinnerung; emotionale Verzerrungen vor allem gefühlsgeprägte Bewertung und Impulse. Die Gruppen können sich überlappen. Korrektur und Anpassung werden nach dem tatsächlichen Mechanismus gewählt.'],
   ['Warum ist geringe Risikofreude kein automatischer Denkfehler?','Eine Präferenz für Stabilität kann bewusst und zum Auftrag passend sein. Ein Biasverdacht verlangt mehr, etwa dass eine wirtschaftlich irrelevante Darstellung bei sonst gleichen Optionen die Entscheidung unangemessen verändert.'],
   ['Was trennt Moderation und Anpassung?','Moderation versucht, den Fehler selbst zu verringern, beispielsweise durch eine korrekte Bezugsgruppe. Anpassung begrenzt die Folgen einer verbleibenden Tendenz durch tragfähige Regeln oder eine passende Aufteilung.'],
   ['Warum ist Conservatism nicht einfach ein vorsichtiges Portfolio?','Der Begriff bezeichnet unzureichende Aktualisierung einer Überzeugung trotz relevanter neuer Daten. Ein niedriges Risiko kann dagegen eine bewusste geeignete Anlegerpräferenz sein.'],
   ['Woran erkennt man Confirmation im Quellenvergleich?','Gleichwertige Information wird unterschiedlich behandelt, weil eine Quelle die vorhandene These stützt und die andere ihr widerspricht. Unterschiedliche methodische Qualität wäre dagegen ein sachlicher Grund für verschiedene Gewichte.'],
   ['Warum sind achtzig Prozent Trefferquote im Signalbeispiel nicht achtzig Prozent Posterior?','Die Trefferquote verwendet die H-Gruppe als Nenner. Die gesuchte Wahrscheinlichkeit verwendet alle positiven Signale einschließlich der vielen Nicht-H-Fälle als Nenner. Von 1140 positiven Signalen gehören nur 160 zu H.'],
   ['Was bedeutet Vernachlässigung kleiner Stichproben?','Eine kurze zufällige Folge wird als besonders repräsentativ für einen stabilen Prozess behandelt. Auswahl vieler beobachteter Manager, Unsicherheit und geeignete Vergleichsgruppen müssen zusätzlich in die Schlussfolgerung eingehen.'],
   ['Warum kann persönliches Orderklicken keine Marktrendite kontrollieren?','Unter gleichen Ausführungsbedingungen verändert die Eingabemethode die gehaltene wirtschaftliche Position nicht. Tatsächliche Limit- oder Ausführungskontrolle ist von Kontrolle künftiger externer Preise zu unterscheiden.'],
   ['Wie hilft ein zeitgestempeltes Journal gegen Hindsight?','Es hält die vor dem Ereignis dokumentierte Unsicherheit fest und verhindert, dass spätere Erinnerung eine frühere sichere Prognose erfindet. Die Kalibrierung der Angaben braucht zusätzlich geeignete wiederholte Fälle.'],
   ['Wann ist der frühere Kaufpreis ein problematischer Anker?','Wenn er ohne eigenständige wirtschaftliche Begründung die heutige Bewertung dominiert. Tatsächliche Steuerfolgen oder Information dürfen berücksichtigt werden; allein der historische Einsatz ist kein neuer Unternehmenscashflow.'],
   ['Warum können Zielkonten nützlich und Mental Accounting trotzdem problematisch sein?','Getrennte Konten können Planung und Selbstbindung unterstützen. Problematisch wird das Ignorieren der gemeinsamen Vermögens-, Risiko- und Zahlungswirkung identischer wirtschaftlicher Bestände.'],
   ['Was muss bei einem Framing-Test konstant bleiben?','Auszahlungen, Wahrscheinlichkeiten, Kosten, Rechte und weitere wirtschaftliche Bedingungen jeder Option. Ändert sich etwas davon tatsächlich, ist eine andere Wahl nicht allein durch die Darstellung erklärt.'],
   ['Warum bedeutet häufige Berichterstattung nicht viele unabhängige Ereignisse?','Mehrere Meldungen können denselben Vorgang wiederholen. Eine Wahrscheinlichkeit benötigt eine passende Grundgesamtheit und Informationen über die tatsächlich verschiedenen Fälle.'],
   ['Warum ist Verlustaversion nicht gleich allgemeiner Risikoaversion?','Verlustaversion betrifft die besondere Bedeutung negativer Veränderungen relativ zu einer Referenz. Eine deskriptive Wertfunktion kann auf der Verlustseite sogar konvex sein und dort eine unsichere Wahl begünstigen.'],
   ['Was zeigen die zwei Referenzen im Achtzig/Neunzig/Hundert-Fall?','Die Endvermögen bleiben identisch, aber derselbe illustrative Bewertungsmechanismus ordnet sie relativ zu hundert als Verluste und relativ zu achtzig als Gewinne ein. Dadurch kann sich die Rangfolge der Scores umkehren.'],
   ['Warum ist nicht jeder Verkauf eines Gewinners ein Disposition Effect?','Übergewichtung, Kosten, Steuern oder veränderte Aussichten können sachliche Gründe liefern. Entscheidend ist, ob allein Gewinnrealisierung und Vermeidung der psychologischen Verlustanerkennung die Wahl treiben.'],
   ['Was ist Überpräzision bei einer Prognose?','Die behauptete Sicherheit beziehungsweise Enge der Prognose ist nicht durch ihre tatsächliche Abdeckung gestützt. Geeignete dokumentierte Vergleichsfälle und deren Abhängigkeit helfen, die Kalibrierung zu beurteilen.'],
   ['Warum kann mehr Handel die Nettorendite mindern?','Jede zusätzliche Umsetzung kann Kosten auf der jeweiligen Handelsbasis verursachen. Der zusätzliche Informationsnutzen muss diese Belastung rechtfertigen; der kontrollierte Vergleich hält die Bruttoleistung gerade fest.'],
   ['Warum kosten zehn Jahre späterer Sparbeginn mehr als nur die ausgelassenen Beiträge?','Die frühen Beiträge hätten über längere Zeit Rendite verdient. Ihre entfallenden Wiederanlageerträge fehlen ebenfalls am gemeinsamen Endtermin.'],
   ['Was trennt Status Quo, Endowment und Regret Aversion?','Status Quo betont die ungeprüfte bestehende Option. Endowment betont die eigene Eigentümerrolle. Regret Aversion betont die Furcht vor späterem Bedauern. Ein konkreter Fall kann mehr als einen Mechanismus enthalten.'],
   ['Kann ein Momentum-Muster allein eine psychologische Ursache beweisen?','Nein. Veränderte Risikoprämien, Daten- und Auswahlfragen oder andere Informationen sind mögliche Alternativen. Ein Muster muss außerdem von einer tatsächlich nach Kosten umsetzbaren Strategie unterschieden werden.'],
   ['Warum kann eine vermutete Fehlbewertung lange bestehen?','Gegenpositionen können vor der erhofften Korrektur weitere Verluste, Leihkosten und Sicherheitenbedarf verursachen. Kapital und Zeithorizont der Gegenhändler sind begrenzt; eine sichere zustandsweise Replikation ist eine andere Situation.'],
   ['Was fehlt einem überzeugenden historischen Backtest noch?','Prüfung von Risikomodell und Datenauswahl, glaubwürdige Evidenz außerhalb der Auswahlstichprobe und eine ausführbare Nettorechnung einschließlich Kosten, Finanzierung und tatsächlichem Zugang.']
  ].map(([q,a])=>D(q,[a]))
 ])
],explorations:[{section:'calculator',lesson:'portfolio-02',focus:'lab',label:'Risikoaversion im Mittelwert-Varianz-Modell: keine Verlustaversion'},{section:'calculator',lesson:'portfolio-10',focus:'lab',label:'Gewichtsdrift als Ausgangspunkt einer vereinbarten Kontrollregel'}],related:[{unit:'ips',section:'conflict',label:'Bereitschaft und finanzielle Fähigkeit zur Risikoübernahme'},{unit:'investment-process',section:'monitoring',label:'Entscheidungsprozess und tatsächliche Überwachung'},{unit:'inference',section:'interpretation',label:'Mehrfachsuche und scheinbar überzeugende Ergebnisse'},{unit:'portfolio-pricing',section:'limitations',label:'Historische Performancemaße und Grenzen der Interpretation'}],sources:[
 {title:'CFA Institute: Level I Topic Outlines 2027, S. 28; verbindliche drei Lernziele von The Behavioral Biases of Individuals',url:'https://www.cfainstitute.org/sites/default/files/2027levelitopicoutline_online.pdf#page=28'},
 {title:'CFA Institute: The Behavioral Biases of Individuals, 2026; öffentliche Begriffsgruppierung und Konzeptübersicht',url:'https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/the-behavioral-biases-of-individuals'},
 {title:'Barber und Odean (2000): Trading Is Hazardous to Your Wealth; historische US-Brokerstichprobe und Nettohandelskosten',url:'https://faculty.haas.berkeley.edu/odean/papers%20current%20versions/individual_investor_performance_final.pdf'},
 {title:'Kahneman und Tversky (1979): Prospect Theory; weiterführende Originalarbeit. Eigene illustrative Wertfunktion ohne behauptete empirische Parameterschätzung',url:'https://kahneman.scholar.princeton.edu/sites/g/files/toruqf3831/files/kahneman/files/prospect_theory.pdf'}
],review:{status:'draft',date:'2026-10-26',note:'Eigene kontrollierte Fälle unterscheiden Verzerrung, legitime Präferenz und wirtschaftliche Restriktion. Illustrative Markt- und Wertfunktionen sind keine empirisch geschätzten Preis- oder Kundenmodelle. Fachliche Gesamtfreigabe bleibt ausstehend.'}};
